create or replace function public.ensure_future_tournaments()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_created integer := 0;\n  v_today date := (now() at time zone 'Asia/Dhaka')::date;\n  v_day date;\n  v_slot public.tournament_slots%rowtype;\n  v_template public.tournament_templates%rowtype;\n  v_today_t public.tournaments%rowtype;\n  v_open_at timestamptz;\nbegin\n  for v_day in select v_today union all select v_today + 1 loop\n    for v_slot in select * from public.tournament_slots where is_enabled = true order by slot_number loop\n      select * into v_template from public.tournament_templates where mode = v_slot.mode limit 1;\n      if not found then continue; end if;\n      v_open_at := now();\n      if v_day = v_today + 1 then\n        select * into v_today_t from public.tournaments where slot_id=v_slot.id and tournament_date=v_today limit 1;\n        if found then\n          v_open_at := greatest(coalesce(v_today_t.completed_at, now()) + interval '1 hour', (((v_today_t.tournament_date + v_today_t.scheduled_end_time + case when v_today_t.scheduled_end_time <= v_today_t.scheduled_start_time then interval '1 day' else interval '0' end) at time zone 'Asia/Dhaka') + interval '1 hour'));\n        end if;\n      end if;\n      insert into public.tournaments (template_id,slot_id,tournament_date,mode,scheduled_start_time,scheduled_end_time,entry_fee,first_prize,second_prize,third_prize,kill_reward,max_players,max_teams,status,registration_opens_at,is_enabled)\n      values (v_template.id,v_slot.id,v_day,v_slot.mode,v_slot.start_time,v_slot.end_time,v_template.entry_fee,v_template.first_prize,v_template.second_prize,v_template.third_prize,v_template.kill_reward,v_template.max_players,v_template.max_teams,'REGISTRATION',v_open_at,true)\n      on conflict (slot_id,tournament_date) do nothing;\n      if found then v_created := v_created + 1; end if;\n    end loop;\n  end loop;\n  return v_created;\nend;\n$function$;\n